package com.gameaggregator.entitlementservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.entitlementservice.application.EntitlementService;import com.gameaggregator.entitlementservice.domain.Entitlement;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/entitlements") public class EntitlementController{final EntitlementService s;public EntitlementController(EntitlementService s){this.s=s;}@PostMapping ApiResponse<Entitlement> create(@Valid @RequestBody EntitlementDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping("/client/{clientId}")ApiResponse<List<Entitlement>> client(@PathVariable UUID clientId){return ApiResponse.success(s.client(clientId));}@PatchMapping("/{id}/status")ApiResponse<Entitlement> status(@PathVariable UUID id,@Valid @RequestBody EntitlementDtos.Status r){return ApiResponse.success(s.status(id,r));}@GetMapping("/check")ApiResponse<EntitlementDtos.Decision> check(@RequestParam UUID clientId,@RequestParam UUID gameId,@RequestParam UUID environmentId,@RequestParam String region){return ApiResponse.success(s.check(clientId,gameId,environmentId,region));}}